\label{injectivelemma}
 Suppose that $i_1,\ldots, i_\ell\in[1,n+1]$ are distinct and set $\mathbf{v} = v_{i_1} \otimes \cdots \otimes v_{i_{\ell}} \in V^{\otimes \ell}$. Then 
 $V^{\otimes \ell} = U(\mathfrak{sl}_{n+1}).\mathbf{v}$ and the map $ M\to M\otimes_{\mathbb{C}[S_\ell]}V^{\otimes\ell} $ defined by $m \mapsto m \otimes\mathbf{v}$ is injective for any $S_{\ell}$--module $M$.

\label{Fprop72}
	For each $i\in [0, n] , k \in \mathbb{Z}$, there exist $\alpha_{j,x_i^\pm(k)},\alpha_{j,h_i(k)} \in \text{End}_{\mathbb{C}}(M)$ with
	\begin{align*}
		x_i^\pm(k).\left(m \otimes_{\mathbb{C}[S_{\ell}]} u^{\mp}_{i,j} \right) &= \alpha_{j,x_i^\pm(k)}(m) \otimes_{\mathbb{C}[S_{\ell}]} u^{\pm}_{i,j}\ \\
		h_i(k).\left(m \otimes_{\mathbb{C}[S_{\ell}]} u^{\pm}_{i,j} \right) &= \pm\alpha_{j,h_i(k)}(m) \otimes_{\mathbb{C}[S_{\ell}]} u^{\pm}_{i,j}\ 
	\end{align*}
	and moreover,
	\begin{align*}
		\big(x_i^\pm(k)\big)_j.u^{\mp}_{i,j} &= u^{\pm}_{i,j};\\
		\big(h_i(k)\big)_j .u^{\pm}_{i,j} &= \pm u^{\pm}_{i,j}.
	\end{align*}

For a fixed $i$, the set $\{ \tau.u^{\pm}_{i,1} \mid \tau \in S_{\ell} \}$ spans the $\mathfrak{sl}_{n+1}$-weight space $V^{\otimes \ell}_{\lambda_{u^{\pm}_{i,1}}}$ of weight $\lambda_{u^{\pm}_{i,1}}$ of $V^{\otimes \ell}$ where
	\begin{align*}
		\lambda_{u^{+}_{i,1}}&=\begin{cases}
			\sum_{p=1}^{\ell+1} \varepsilon_p-\varepsilon_{i+1},\text{ if } 1\le i\le \ell;\\
			\sum_{p=1}^{\ell-1} \varepsilon_p+\varepsilon_{i},\text{ if } \ell+1 \le i\le n;\\
			\sum_{p=2}^{\ell} \varepsilon_p+\varepsilon_{n+1},\text{ if } i=0
		\end{cases}
	\end{align*}
	and $\lambda_{u^{-}_{i,1}}=\lambda_{u^{+}_{i,1}}-\alpha_i$. Indeed, using the action from \S \ref{classicalaffineswd}, for any $h_i (0), i = 1, \ldots , n$, we have
	$$h_i (0) . v_j = 
	(\delta_{j,i} - \delta_{j,i+1}) v_j = \varepsilon_j (h_i) v_j.$$
	Thus $v_j$ is of weight $\varepsilon_j$ and hence $h_j (k).\tau.u^{\pm}_{i,1} = \lambda_{u^{\pm}_{i,1}} (h_j) \tau.u^{\pm}_{i,1}$ and so $\tau. u^{\pm}_{i,1}$ is of $\mathfrak{sl}_{n+1}$-weight $\lambda_{u^{\pm}_{i,1}}$.
	
	Now, a direct computation shows that $h_i (0).\tau.u^{+}_{i,1} = \lambda_{u^{\pm}_{i,1}}(h_i (0))\tau.u^{+}_{i,1}=\tau.u^{+}_{i,1}$. Similarly, we see that $h_i (0).\tau.u^{-}_{i,1}= -\tau.u^{-}_{i,1}$. It follows from these calculations and Theorem \ref{nonquantumuntwistedequiv} that for every $m \in M$, we have $h_i (0).\left(m \otimes_{\mathbb{C}[S_{\ell}]} u^{\pm}_{i,1} \right) = \pm m \otimes_{\mathbb{C}[S_{\ell}]} u^{\pm}_{i,1}$, so $m \otimes_{\mathbb{C}[S_{\ell}]} u^{\pm}_{i,1}$ is in the weight space $W_{\lambda_{u^{\pm}_{i,1}}}$.
	
	The relations in $\mathfrak{sl}_{n+1}[s^{\pm 1}, t^{\pm 1}]$ show that $h_i (k)$ must take $m\otimes_{\mathbb{C}[S_{\ell}]} u^{\pm}_{i,1}$ to a vector of weight $\lambda_{u^{\pm}_{i,1}}$ since if $w$ has weight $\lambda_{u^{\pm}_{i,1}}$ we must have, for $1\le j \le n$,  $h_j(0)h_i(k).w=h_i(k)h_j(0).w=\lambda_{u^{\pm}_{i,1}}(h_j)h_i(k).w$. And since $\{ \tau.u^{\pm}_{i,1} \mid \tau \in S_{\ell} \}$ spans the subspace of $V^{\otimes \ell}$ of its associated weight, then $h_i (k)$ must take $m \otimes_{\mathbb{C}[S_{\ell}]} u^{\pm}_{i,1}$ to a sum of terms of the form $m_\tau\otimes \tau.u^{\pm}_{i,1}$ for some $m_\tau$ (well-defined since $W$ is an $\mathfrak{sl}_{n+1}[s^{\pm 1}, t^{\pm 1}]$--module). Now, for each $m \in M$ we have:
	\begin{align*}
		h_i (k).\left(m \otimes_{\mathbb{C}[S_{\ell}]} u^{\pm}_{i,1} \right) &= \sum_{\tau \in S_{\ell}} m_{\tau} \otimes_{\mathbb{C}[S_{\ell}]} \lambda_{u^{\pm}_{i,1}}(h_i) \tau.u^{\pm}_{i,1} \\
		& = \sum_{\tau \in S_{\ell}} m_{\tau}.\tau \otimes_{\mathbb{C}[S_{\ell}]} \lambda_{u^{\pm}_{i,1}}(h_i) u^{\pm}_{i,1}\\
		& = \pm m' \otimes_{\mathbb{C}[S_{\ell}]} u^{\pm}_{i,1}
	\end{align*}
	where $m' = \sum_{\tau \in S_{\ell}} m_{\tau}.\tau$. Note that this $u^{\pm}_{i,1}$ meets the conditions of Lemma \ref{injectivelemma}. Therefore each such $m'$ can be recovered from $m' \otimes_{\mathbb{C}[S_{\ell}]} u^{\pm}_{i,1} $. Then there exists $\alpha_{1,h_i(k)} \in \text{End}_{\mathbb{C}}(M)$ with the property that, for each $m \in M$, we can find $m'$ such that $m' = \alpha_{1,h_i(k)} (m)$.
	Defining $\alpha_{j,h_i(k)}(m)=\alpha_{1,h_i(k)}(m.\sigma).\sigma^{-1}$ we see that 
	\begin{align*}
		h_i (k). \left(m \otimes_{\mathbb{C}[S_{\ell}]} u^{\pm}_{i,j} \right)&=h_i (k). \left(m. \sigma \otimes_{\mathbb{C}[S_{\ell}]} \sigma^{-1}. u^{\pm}_{i,j} \right)\\
		&=h_i (k). \left(m.\sigma \otimes_{\mathbb{C}[S_{\ell}]} u^{\pm}_{i,1} \right)\\
		&=\pm(\alpha_{1,h_i(k)}(m.\sigma) \otimes_{\mathbb{C}[S_{\ell}]} u^{\pm}_{i,1})\\
		&=\pm(\alpha_{1,h_i(k)}(m.\sigma).\sigma^{-1} \otimes_{\mathbb{C}[S_{\ell}]} \sigma.u^{\pm}_{i,1})\\
		&=\pm(\alpha_{j,h_i(k)}(m) \otimes_{\mathbb{C}[S_{\ell}]} u^{\pm}_{i,j}).
	\end{align*}
	
	Now assume $w$ has weight $\lambda$. By relations in $\mathfrak{sl}_{n+1}[s^{\pm 1}, t^{\pm 1}]$, for any $w \in W, 1\le i \le n$, we have 
	\begin{align*}
		h_i (0) x_j^{\pm} (k') . w &= (x_j^{\pm} (k') h_i (0) \pm \alpha_j (h_i(0)) x_j^{\pm} (k')).w\\
		& = (\lambda \pm \alpha_j) (h_i(0)) x_j^{\pm} (k').w.
	\end{align*}
	Thus $x_j^{\pm} (k')$ adds $\pm \alpha_j = \pm (\varepsilon_j - \varepsilon_{j+1})$ to the weight if $j = 1, \ldots , n$, or adds $\alpha_0 = \mp (\varepsilon_1 - \varepsilon_{n+1})$ to the weight if $j = 0$. In particular, by direct calculation, the weight of $x_j^{\pm} (k').u^{\mp}_{j,1}$ is the same as the weight of $u^{\pm}_{j,1}$. We conclude that for every $m \in M$, $x_j^{\pm} (k').\left(m \otimes_{\mathbb{C}[S_{\ell}]} u^{\mp}_{j,1} \right) = \sum_{\tau \in S_{\ell}} m_{\tau} \otimes_{\mathbb{C}[S_{\ell}]} \tau.u^{\pm}_{j,1}$ for some $m_{\tau} \in M$. An argument similar to the one above proves the existence of the $\alpha_{j,x_i^\pm(k)}$ with the properties in the Lemma statement.

\label{Fprop73}
For all $z \in \{ h_i (k), x_i^{\pm} (k) \mid i = 0, \ldots , n \text{ and } k \in \mathbb{Z} \}$, $m \in M$ (with $M$ as in Lemma \ref{Fprop72}), and $\mathbf{v} \in V^{\otimes \ell}$, we have 
$$z.(m \otimes_{\mathbb{C}[S_{\ell}]} \mathbf{v}) = \sum_{1 \leq p \leq \ell} \alpha_{p,z}(m) \otimes_{\mathbb{C}[S_{\ell}]} z_p. \mathbf{v}.$$

Let $z = x_i^{+} (k), i = 2, \ldots , n$ (in particular, $n \geq 2$; note that, if $n=1$, then $\ell=1$, in which case Lemma \ref{Fprop73} reduces to Lemma \ref{Fprop72}). Other cases are similar and are omitted.

Let $r$ (resp. $s$) be the number of tensor factors in $\mathbf{v}$ containing $v_i$ (resp. $v_{i+1}$). Given $\mathbf{v}$, write $\bar{r}(\mathbf{v})$ for the number $r$ in $\mathbf{v}$, and similarly for $\bar{s}$, giving $s$. We will prove the statement of the lemma for all $\mathbf{v} \in V^{\otimes \ell}$ via induction. First induct on $r$.

Base case: if $r=s=0$, then the sum $\sum_{1 \leq p \leq \ell} \alpha_{p,x_i^{+} (k)}(m) \otimes_{\mathbb{C}[S_{\ell}]} \big(x_i^{+} (k) \big)_p . \mathbf{v} = 0$ since $x_i^{+} (k).\mathbf{v}=0$. Now, $x_i^{\pm} (k).(m \otimes_{\mathbb{C}[S_{\ell}]} \mathbf{v}) = \frac{1}{2} \left( h_i(k) x_i^{\pm}(0) - x_i^{\pm}(0) h_i(k) \right).(m \otimes_{\mathbb{C}[S_{\ell}]} \mathbf{v})$. By Theorem \ref{nonquantumuntwistedequiv}, $x_i^{\pm}(0) .(m \otimes_{\mathbb{C}[S_{\ell}]} \mathbf{v}) =  m \otimes_{\mathbb{C}[S_{\ell}]} x_i^{\pm}(0).\mathbf{v} = 0$, and $h_i(k)$ preserves the weight space of $m \otimes_{\mathbb{C}[S_{\ell}]} \mathbf{v}$, so $x_i^{\pm}(0)$ applied to $h_i (k) (m \otimes_{\mathbb{C}[S_{\ell}]} \mathbf{v})$ is 0. Hence both terms are 0, proving the Lemma when $r=s=0$.

Inductive step: assume that $\mathbf{v}$ is such that $\bar{r}(\mathbf{v})=r+1$ and $\bar{s}(\mathbf{v})=s$. Then there exists $k_0 \in \{ 1 , \ldots , n \}$ such that:
\begin{enumerate}
    \item $v_{k_0}$ does not appear in $\mathbf{v}$ (since $\ell \leq n$);
    \item we may assume that $k_0 = i-1$ ($n \geq 2$). Otherwise there exists $\rho \in W(\mathfrak{sl}_{n+1})$, the Weyl group of $\mathfrak{sl}_{n+1}$, such that $\rho(k_0) = i-1$ and $\rho(i)=i, \rho(i+1)=i+1$. Then $\bar{r}(\rho(\mathbf{v}))=r+1, \bar{s}(\rho(\mathbf{v}))=s$ and $\mathbf{v}$ has no copies of $v_{i-1}$.
\end{enumerate}
If $\ell \geq 2$, take $p$ such that $i_p=i$ (which is possible if $\ell \geq 2$, since $r+1>0$) and define $\mathbf{w}$ such that $w_{i_q}=v_{i_q}$ for $q \neq p$ and $w_{i_p}=v_{i-1}$. Then $\mathbf{v} = x^{-}_{i-1} (0) \mathbf{w}$ and $\bar{r}(\mathbf{w})=r, \bar{s}(\mathbf{w})=s$, so we can apply the induction hypothesis to $\mathbf{w}$. So
\begin{align*}
    x_i^{+} (k). (m \otimes_{\mathbb{C}[S_{\ell}]} \mathbf{v}) &= x_i^{+} (k) x_{i-1}^{-} (0). (m \otimes_{\mathbb{C}[S_{\ell}]} \mathbf{w}) = x_{i-1}^{-} (0) x_i^{+} (k) .(m \otimes_{\mathbb{C}[S_{\ell}]} \mathbf{w}) \\
    &= x_{i-1}^{-} (0) \sum_{1 \leq p \leq \ell} \alpha_{p, x_i^{+} (k)}(m) \otimes_{\mathbb{C}[S_{\ell}]} \big(x_i^{+} (k) \big)_p . \mathbf{w} \\
    &= \sum_{1 \leq p \leq \ell} \alpha_{p, x_i^{+} (k)}(m) \otimes_{\mathbb{C}[S_{\ell}]} \big(x_i^{+} (k) \big)_p . \mathbf{v},
\end{align*}
which proves the statement of the lemma for all $r$ by induction. (If $\ell=1$, take $\mathbf{v}=v_i$ and $\mathbf{w}=v_{i-1}$ and perform the same computation above.) A similar argument establishes the statement for all $s$, completing the proof of the lemma.

In this proof, by $\rho_i(x)$ for $x \in \mathfrak g$ we will mean $(\rho_i \circ \iota_{i,0})(x)$. By (i), this means that $\rho_i(x)=\rho_j(x)$.
We now prove the statement of the proposition by induction on $m$. The statement is vacuously true if $m=1$. For the inductive step, we proceeds as follows.


For all $x\in \mathfrak g$ choose a decomposition $x = \sum_{j} [x_{j}', x_{j}'']$ (a finite sum). We define inductively:
$$
\rho(x \otimes t_1^{p_1}t_2^{p_2} \cdots t_m^{p_m})=\sum_{j} [\rho(x_{j}' \otimes t_1^{p_1} \cdots t_{m-1}^{p_{m-1}}), \rho_m(x_{j}'' \otimes t_m^{p_m})], \hspace{3mm} m>1.$$



We need to show two facts: (1) $\rho$ is well-defined, i.e. it doesn't depend on the choice of decomposition, (2) $\rho$ does indeed define a Lie algebra homomorphism. The main step of this argument is to show that $\rho$, assumed well-defined for $m-1$, can be expressed in the form:
\begin{equation}
\rho(x\otimes t^{\mathbf p} )=\sum_{x_{1}',\dots, x_{m}' \in \mathfrak g}[\rho_{m}(x_{m}'\otimes t_{m}^{p_{m}}), [\rho_{m-1}(x_{m-1}'\otimes t_{{m-1}}^{p_{m-1}}), \cdots[\rho_{2}(x_{2}'\otimes t_{2}^{p_{2}}),\rho_1(x_{1}' \otimes t_{1}^{p_{1}})]\cdots ]] \label{eq:rhobracket}
\end{equation}
where
$$
x=\sum_{x_{1}',\dots, x_{m}' \in \mathfrak g}[x_{m}', [x_{m-1}', \cdots[x_{2}',x_{1}' ]\cdots ]].
$$
This is clear when $m=0,1$ so assume that (\ref{eq:rhobracket}) holds for $m-1$, and compute:
\begin{align*}
&\sum_{j} [\rho(x_{j}' \otimes t_{1}^{p_1} \cdots t_{{m-1}}^{p_{m-1}}), \rho_m(x_{j}'' \otimes t_m^{p_m})]=\sum_{j} [ \rho_m(-x_{j}'' \otimes t_m^{p_m}),[\rho(x_{j}' \otimes t_{1}^{p_1} \cdots t_{{m-1}}^{p_{m-1}})]]\\
&=\sum_j\sum_{x_{1,j}',\dots, x_{m-1,j}' \in \mathfrak g} [\rho_m(-x_{j}''\otimes t_m^{p_m}),[\rho_{m-1}(x_{m-1,j}'\otimes t_{m-1}^{p_{m-1}}), [ \cdots[\rho_{2}(x_{2,j}'\otimes t_{2}^{p_{2}}),\rho_1(x_{1,j}' \otimes t_{1}^{p_{1}})]\cdots ]]]
\end{align*}
where
\begin{align*}
\sum_j\sum_{x_{1,j}',\dots, x_{m-1,j}' \in \mathfrak g} [-x_{j}'',[x_{m-1,j}', [ \cdots[x_{2,j}',x_{1,j}' ]\cdots ]]]=\sum_j[-x_j'',x_j']=x
\end{align*}
as desired.

Now, we use (\ref{eq:rhobracket}) to prove that $\rho$ is well-defined on $L^m(\mathfrak g)$. In particular, it is independent of the chosen decomposition. Let $x=\sum_i [x_{i,1}',x_{i,1}'']=\sum_i[x_{i,2}',x_{i,2}'']$ be two distinct decompositions and use (\ref{eq:rhobracket}) to write
\begin{align*}
&\sum_{j=1}^2(-1)^j\sum_i [\rho(x_{i,j}'\otimes t_1^{p_1}t_2^{p_2}\cdots t_{m-1}^{p_{m-1}}),\rho_m(x_{i,j}''\otimes t_m^{p_m})]\nonumber\\
&=\sum_{j=1}^2(-1)^j\sum_i\sum_{x_{i,j,1}',\dots, x_{i,j,m-1}' \in \mathfrak g}[-\rho_m(x_{i,j}''\otimes t_m^{p_m}),[\rho_{m-1}(x_{i,j,m-1}'\otimes t_{m-1}^{p_{m-1}}), [\cdots[\rho_{2}(x_{i,j,2}'\otimes t_{2}^{p_{2}}),\rho_1(x_{i,j,1}' \otimes t_{1}^{p_{1}})]\cdots ]]].\label{eq:decomp}
\end{align*}
Now, observe that, by our choices
$$
\sum_{j=1}^2(-1)^j\sum_i\sum_{x_{i,j,1}',\dots, x_{i,1,m-1}' \in \mathfrak g}[-x_{i,j}'',[x_{i,j,m-1}', [\cdots [x_{i,j,2}',x_{i,j,1}']\cdots ]]]=\sum_{j=1}^2(-1)^j\sum_i[x_{i,j}',x_{i,j}'']=x-x=0.
$$
Therefore condition (ii) applies to show:
$$
\sum_i [\rho(x_{i,1}'\otimes t_1^{p_1}t_2^{p_2}\cdots t_{m-1}^{p_{m-1}}),\rho_m(x_{i,1}''\otimes t_m^{p_m})]=\sum_i [\rho(x_{i,2}'\otimes t_1^{p_1}t_2^{p_2}\cdots t_{m-1}^{p_{m-1}}),\rho_m(x_{i,2}''\otimes t_m^{p_m})].
$$
Hence, the decomposition of $x$ does not affect the definition of $\rho.$



Now we show that $\rho$ is a homomorphism of  Lie algebras. 
We want to show that $$
[\rho(x\otimes t^\mathbf s),\rho(y\otimes t^\mathbf r)]=\rho([x,y]\otimes t^{\mathbf s + \mathbf r}),\ \ x,y\in\mathfrak  g, \   \mathbf r, \mathbf s\in\mathbb Z^m.
$$
Write $\mathbf r = (r_1, \ldots , r_m), \mathbf s = (s_1, \ldots , s_m)$. We first check the equality in the case when $s_j=0$ for all $j$. Here the result holds by definition. Then we assume that this has been proved for $s_j=0$ for $j>p$ and prove it for $s_j=0$ with $j>p+1$.
By (\ref{eq:rhobracket}) we write:
$$
\rho(y\otimes t^{\mathbf r} )=\sum_{y_{1}',\dots, y_{m}' \in \mathfrak g}[\rho_m(y_m'\otimes t_m^{r_m}), [\rho_{m-1}(y_{m-1}'\otimes t_{{m-1}}^{r_{m-1}}), \cdots[\rho_2(y_2'\otimes t_2^{r_2}),\rho_1(y_1' \otimes t_1^{r_1})]\cdots ]].
$$
Then:
\begin{align*}
&\sum_{y_{1}',\dots, y_{m}' \in \mathfrak g}[\rho_1(x\otimes t_1^{s_1}),[\rho_m(y_m'\otimes t_m^{r_m}), [\rho_{m-1}(y_{m-1}'\otimes t_{m-1}^{r_{m-1}}), \cdots[\rho_2(y_2'\otimes t_2^{r_2}),\rho_1(y_1' \otimes t_1^{r_1})]\cdots ]]]\\
&=\sum_{y_1',\dots, y_m' \in \mathfrak g}[\rho_m(x\otimes t_m^{r_m}),[\rho_{m-1}(y_{m}'\otimes t_{m-1}^{r_{m-1}}), [ \cdots[\rho_{1}(y_2'\otimes t_1^{r_1}),\rho_1(y_1' \otimes t_1^{s_1})]\cdots ]]]\\
&=\sum_{y_1',\dots, y_m' \in \mathfrak g}[\rho_m(x\otimes t_m^{r_m}),[\rho_{m-1}(y_m'\otimes t_{m-1}^{r_{m-1}}), [ \cdots[\rho_2(y_3'\otimes t_2^{r_2}),\rho_{1}([y_2',y_1']\otimes t_1^{r_1+s_1})]\cdots ]]]\\
&=\rho([x,y]\otimes t^{\mathbf r}t_1^{s_1})
\end{align*}
using (iii) in the second line to permute the $\rho_{i}$ and powers of $t_i$.
Now, assume $\rho$ is a homomorphism for $1\le p < m$. The definition of $\rho$ gives:
$$
\rho(x\otimes t_1^{s_1}\cdots t_{p+1}^{s_{p+1}})=\sum_j [\rho(x_j'\otimes t_1^{s_1}\cdots t_{p}^{s_{p}}),\rho_u(x_j''\otimes t_{p+1}^{s_{p+1}})].
$$
An argument similar to the one given above shows that, for all $z \in \mathfrak g$
$$
[\rho_{p+1}(z\otimes t_{p+1}^{s_{p+1}}), \rho(y\otimes t^{\mathbf r})]=\rho([z,y]\otimes t^{\mathbf r}t_{p+1}^{s_{p+1}}).
$$
Finally, we use the Jacobi Identity and induction to write:
\begin{align*}
    &\left [\sum_j [\rho(x_j'\otimes t_1^{s_1}\cdots t_{p}^{s_{p}}),\rho_{p+1}(x_j''\otimes t_{p+1}^{s_{p+1}})], \rho(y\otimes t^{\mathbf r})\right ]\\
    &=\sum_j([\rho(x_j'\otimes t_1^{s_1}\cdots t_p^{s_p}),[\rho_{p+1}(x_j''\otimes t_{p+1}^{s_{p+1}}), \rho(y\otimes t^{\mathbf r})]]-[\rho_{p+1}(x_j''\otimes t_{p+1}^{s_{p+1}}), [\rho(x_j'\otimes t_1^{s_1}\cdots t_p^{s_p}),\rho(y\otimes t^{\mathbf r})]])\\
    &=\rho\left(\sum_j([x_j',[x_j'',y]]-[x_j'', [x_j',y]])\otimes t^{\mathbf s + \mathbf r}\right )\\
    &=\rho([x,y]\otimes t^{\mathbf r + \mathbf s}).
\end{align*}


Hence the proposition is proved. The maps and algebras involved are collected in the following commutative diagram.

                                       

