\label{uniqueliftedmodstruc}
Let $A_i$ for $i=1, 2, \ldots , m$ be a collection of subalgebras of an associative algebra $A$ such that the $A_i$ generate $A$.
\begin{itemize}
\item[(a)] For all $A$--modules $M,N$ with linear map $f : M \to N$, the map $f$ is an $A$-homomorphism if and only if $f$ is an $A_i$-homomorphism for each $i$.
\item[(b)] Given algebra homomorphisms $\phi: A \to B$ and $\phi': A \to B$, if $\phi|_{A_i}= \phi'|_{A_i}$ for each $i$, then $\phi = \phi'$.
\end{itemize}

\label{classicaluntwistedtoroidalheckem}
Define $\operatorname{Aff}^m(S_{\ell})$ to be the unital associative algebra over $\mathbb{C}$ with generators $\sigma^{\pm 1}_i$, $i \in [1, \ell-1 ]$, $\mathbf{y}_{1,r}$, ..., $\mathbf{y}_{m,r}$,  $r \in [1, \ell ]$ and relations

\begin{gather*}
 \sigma_k \sigma^{-1}_k = \sigma^{-1}_k \sigma_k = 1,\ \ 
\sigma_k \sigma_{k+1} \sigma_k = \sigma_{k+1} \sigma_k \sigma_{k+1},\\
 \sigma_k \sigma_j = \sigma_j \sigma_k,\ \  \vert k-j \vert > 1,\ \
 \sigma_k^2 = 1,\ \\ 
 \mathbf{y}_{i,s} \mathbf{y}_{i,s}^{-1} = \mathbf{y}_{i,s}^{-1} \mathbf{y}_{i,s} = 1, \ \mathbf{y}_{i,s} \mathbf{y}_{i,p} = \mathbf{y}_{i,p} \mathbf{y}_{i,s}, \\
 \mathbf{y}_{i,s} \sigma_k = \sigma_k \mathbf{y}_{i,s},\ \ s \notin \{ k, k+1 \}\\ \sigma_k \mathbf{y}_{i,k} \sigma_k = \mathbf{y}_{i,{k+1}}, 
 \\ \mathbf{y}_{i,1} \cdots \mathbf{y}_{i,{\ell}} \mathbf{y}_{{i'},1} = \mathbf{y}_{{i'},1} \mathbf{y}_{i,1} \cdots \mathbf{y}_{i,{\ell}},\ \  \ \ \mathbf{y}_{{i'},1} \mathbf{y}_{i,2}= \mathbf{y}_{i,2} \mathbf{y}_{{i'},1}
\end{gather*}
for $k \in [1, \ell-2 ]$ in the second relation; $i, i' \in [1, m]$; $k,j \in [1, \ell-1 ]$ otherwise; and $p,s \in [1, \ell ]$.\hfill

Let $ G$ be any group. For any system of group homomormphisms: $\rho_i: \operatorname{Aff}_i(S_{\ell}) \to G$ satisfying the conditions 
\begin{itemize}
\item[(i)] $\rho_i\circ \nu_0=\rho_j\circ\nu_0$, (so denote $ \rho_0=\rho_i\circ \nu_0: S_{\ell}\to G$), and 
\item[(ii)] $ \rho_i\ker(ev_i) \rho_j\ker(ev_j)= \rho_j\ker(ev_j) \rho_i\ker(ev_i) $ for all $ i, j$, 
                                                                                                                                                                             
\end{itemize}
there is a unique group homomorphism $\rho: \operatorname{Aff}^m(S_{\ell})\to G$ such that $\rho_i=\rho\circ \nu_i$.

\label{mainliftingthm}
Let  $\ell, m\geq 1$ be integers with $\mathfrak{g}=\mathfrak{sl}_{n+1}$ and $ \ell\leq n$. Then
\begin{itemize}
\item[(a)] For any $ \mathbb{C}[\operatorname{Aff}^m(S_{\ell})] $--module $M$
there is a unique $L^m(\mathfrak g)$--module structure on $ \mathcal F(M)=M\otimes_{\mathbb{C}[S_{\ell}]} V^{\otimes {\ell}}$ extending the $L_i(\mathfrak g)$--module structures given by Theorem \ref{nonquantumuntwistedequiv}.
\item[(b)] $\mathcal F:  \operatorname{Mod-}\mathbb{C}[\operatorname{Aff}^m(S_{\ell})]\to 
L^m(\mathfrak{g})\operatorname{-Mod}$ is a fully faithful functor.
\item[(c)] Let $L^m(\mathfrak g)\operatorname{-Mod}^{\ell}$ be the full subcategory of  all $L^m(\mathfrak g)$--modules whose restriction to $ \mathfrak g$ via $\iota_0^m$ is locally finite dimensional and all composition factors are the composition factors of $ V^{\otimes {\ell}}$. Then $ \mathcal F: \operatorname{Mod-}\mathbb{C}[\operatorname{Aff}^m(S_{\ell})]\to 
L^m(\mathfrak g)\operatorname{-Mod}^{\ell}$ is a category equivalence. 
\end{itemize}
